fn parse_int(s: Str) -> Option<Int> {
    if str_len(s) == 0 {
        None
    } else {
        let mut n: Int = 0
        let mut i: Int = 0
        if s.get(0).expect("out-of-bounds") == "-" {
            i = i + 1
        }
        while i < str_len(s) {
            let c = s.get(i).expect("out-of-bounds")
            let d = char_to_digit(c)
            if d.is_none() {
                return None
            }
            n = n * 10 + d.unwrap()
            i = i + 1
        }
        if s.get(0).expect("out-of-bounds") == "-" {
            Some(trunc(n) * -1)
        } else {
            Some(n)
        }
    }
}

