    match c {
      '0'..='9' => {
        total += c.to_digit(10).unwrap() as usize;
        count += 1;
      }
      _ => ()
    }
  }
  println!("Total: {}", total);
  println!("Count: {}", count);
}

fn main() {
  let text = "a1b22";
  let total: usize = text.chars().filter(|&c| c.is_ascii_digit()).map(|c| c.to_digit(10).unwrap() as usize).sum();
  let count: usize = text.chars().filter(|&c| c.is_ascii_digit()).count();
  println!("Total: {}", total);
  println!("Count: {}", count);
}

