fn get(list: Box<List>, i: Int) -> Option<Int> {
    let mut n = list
    let mut i = i
    while letSome(x) == n.head {
        if i == 0 {
            return Some(x)
        }
        i = i - 1
        n = n.tail?
    }
    None
}

